    "selector" : "node",
    "css" : {
      "border-width" : 1.0,
      "height" : 50.0,
      "font-size" : 23,
      "background-opacity" : 1.0,
      "width" : 50.0,
      "background-color" : function(ele) {
        var layer = ele.data('layer');
        if (layer === 'genetic'){
          var node_degree = ele.data('node_degree')/156;
          var baseColor = [144, 28, 162];
        } else if (layer === 'molecular') {
          var node_degree = (ele.data('node_degree')-1000)/154;
          var baseColor = [7, 140, 7];
        } else if (layer === 'pet') {
          var node_degree = (ele.data('node_degree')-2000)/174;
          var baseColor = [180, 0, 0];
        } else if (layer === 'mri') {
          var node_degree = (ele.data('node_degree')-3000)/165;
          var baseColor = [5, 68, 70];
        } else if (layer === 'riskfactors') {
          var node_degree = (ele.data('node_degree')-5000)/147;
          var baseColor = [109, 112, 4];
        } else if (layer == 'phenotype') {
          var node_degree = (ele.data('node_degree')-4000)/189;
          var baseColor = [87, 87, 220];
        }
        var colorValue = Math.floor((1-node_degree) * 255);
        // Crea el gradiente de color utilizando el valor de color calculado
        var redValue = baseColor[0] + colorValue;
        var greenValue = baseColor[1] + colorValue;
        var blueValue = baseColor[2] + colorValue;
        // Asegura que los valores RGB estén dentro del rango válido de 0 a 255
        redValue = Math.max(0, redValue);
        greenValue = Math.max(0, greenValue);
        blueValue = Math.max(0, blueValue);
        redValue = Math.min(255, redValue);
        greenValue = Math.min(255, greenValue);
        blueValue = Math.min(255, blueValue);
        return 'rgb(' + redValue + ',' + greenValue + ',' + blueValue + ')';
      },
      "border-opacity" : 1.0,
      "border-color" : function(ele) {
          var backgroundColor = ele.css("background-color");
          var rgbArray = backgroundColor.match(/\d+/g);
          var r = parseInt(rgbArray[0]);
          var g = parseInt(rgbArray[1]);
          var b = parseInt(rgbArray[2]);
          var brightness = ((r * 299) + (g * 587) + (b * 114)) / 1000;
          if (brightness > 125) {
            return '#000000';
          } else {
            return '#ffffff';
          }
        },
      "font-family" : "sans-serif",
      "font-weight" : "bold",
      "text-valign" : "center",
      "text-halign" : "center",
      "text-wrap": "wrap",
      "text-max-width": 50.0,
      "color": function(ele) {
        var backgroundColor = ele.css("background-color");
        var rgbArray = backgroundColor.match(/\d+/g);
        var r = parseInt(rgbArray[0]);
        var g = parseInt(rgbArray[1]);
        var b = parseInt(rgbArray[2]);
        var brightness = ((r * 299) + (g * 587) + (b * 114)) / 1000;
        if (brightness > 125) {
          return '#000000';
        } else {
          return '#ffffff';
        }
      },
      "text-opacity" : 1.0,
      "shape" : "ellipse",
      "content" : "data(name)"
    }
